//! Repository tasks. `cargo xtask spec` regenerates the files derived from
//! `spec/openapi.json`; `cargo xtask spec --check` fails when they drift.

use std::collections::BTreeMap;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode, Stdio};

use heck::{ToSnakeCase, ToUpperCamelCase};
use serde_json::Value;

const SPEC: &str = "spec/openapi.json";
const OP_FILE: &str = "src/op.rs";
const CODE_FILE: &str = "src/error/code.rs";
const HEADER: &str =
    "// @generated by `cargo xtask spec` from spec/openapi.json. Do not edit by hand.\n\n";
const METHODS: [&str; 5] = ["get", "post", "put", "patch", "delete"];

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let result = match args
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>()
        .as_slice()
    {
        ["spec"] => spec(false),
        ["spec", "--check"] => spec(true),
        _ => Err("usage: cargo xtask spec [--check]".into()),
    };
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("{message}");
            ExitCode::FAILURE
        }
    }
}

fn spec(check: bool) -> Result<(), String> {
    let root = workspace_root();
    let spec_text = std::fs::read_to_string(root.join(SPEC))
        .map_err(|error| format!("cannot read {SPEC}: {error}"))?;
    let spec: Value =
        serde_json::from_str(&spec_text).map_err(|error| format!("{SPEC} is not JSON: {error}"))?;
    let operations = operations(&spec)?;
    let outputs = [
        (OP_FILE, rustfmt(&render_ops(&operations))?),
        (CODE_FILE, rustfmt(&render_error_codes(&spec)?)?),
    ];
    let mut drift = Vec::new();
    for (relative, content) in outputs {
        let path = root.join(relative);
        if check {
            if std::fs::read_to_string(&path).ok().as_deref() != Some(content.as_str()) {
                drift.push(relative);
            }
        } else {
            std::fs::write(&path, content)
                .map_err(|error| format!("cannot write {relative}: {error}"))?;
            println!("wrote {relative}");
        }
    }
    if drift.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "generated files are stale: {}. Run `cargo xtask spec`.",
            drift.join(", ")
        ))
    }
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("xtask lives one level below the workspace root")
        .to_path_buf()
}

struct Operation {
    id: String,
    variant: String,
    method: String,
    path: String,
    params: Vec<(String, String)>,
}

fn operations(spec: &Value) -> Result<Vec<Operation>, String> {
    let paths = spec["paths"]
        .as_object()
        .ok_or("spec has no paths object")?;
    let mut by_key = BTreeMap::new();
    for (path, item) in paths {
        for method in METHODS {
            let Some(id) = item[method]["operationId"].as_str() else {
                continue;
            };
            let params = path
                .split('/')
                .filter_map(|segment| segment.strip_prefix('{')?.strip_suffix('}'))
                .map(|name| (name.to_string(), name.to_snake_case()))
                .collect();
            let operation = Operation {
                id: id.to_string(),
                variant: id.to_upper_camel_case(),
                method: method.to_ascii_uppercase(),
                path: path.clone(),
                params,
            };
            if by_key
                .insert((path.clone(), method.to_string()), operation)
                .is_some()
            {
                return Err(format!("duplicate operation {method} {path}"));
            }
        }
    }
    let operations: Vec<Operation> = by_key.into_values().collect();
    let mut variants: Vec<&str> = operations.iter().map(|op| op.variant.as_str()).collect();
    variants.sort_unstable();
    if let Some(duplicate) = variants.windows(2).find(|pair| pair[0] == pair[1]) {
        return Err(format!("two operationIds map to variant {}", duplicate[0]));
    }
    Ok(operations)
}

fn render_ops(operations: &[Operation]) -> String {
    let mut out = String::from(HEADER);
    out.push_str("use crate::http::segment;\n\n");
    out.push_str(
        "/// One variant per operation in the spec that has an `operationId`. An SDK method\n\
         /// sends a request only by constructing a variant, so a variant that no method\n\
         /// constructs is an operation the SDK does not cover, and the build fails on it.\n\
         #[deny(dead_code)]\n\
         #[derive(Clone, Copy, Debug)]\n\
         pub(crate) enum Op<'a> {\n",
    );
    for op in operations {
        out.push_str(&format!(
            "    /// `{} {}` (`{}`)\n    {}",
            op.method, op.path, op.id, op.variant
        ));
        if !op.params.is_empty() {
            let fields: Vec<String> = op
                .params
                .iter()
                .map(|(_, field)| format!("{field}: &'a str"))
                .collect();
            out.push_str(&format!(" {{ {} }}", fields.join(", ")));
        }
        out.push_str(",\n");
    }
    out.push_str("}\n\nimpl Op<'_> {\n");
    out.push_str("    /// The spec's `operationId`.\n    pub(crate) const fn id(self) -> &'static str {\n        match self {\n");
    for op in operations {
        out.push_str(&format!(
            "            Op::{}{} => \"{}\",\n",
            op.variant,
            wildcard(op),
            op.id
        ));
    }
    out.push_str("        }\n    }\n\n");
    out.push_str("    pub(crate) const fn method(self) -> &'static str {\n        match self {\n");
    for op in operations {
        out.push_str(&format!(
            "            Op::{}{} => \"{}\",\n",
            op.variant,
            wildcard(op),
            op.method
        ));
    }
    out.push_str("        }\n    }\n\n");
    out.push_str(
        "    /// The request path with every parameter percent-encoded as one segment.\n\
         /// Returns the parameter's name when its value is empty, `.` or `..`, because\n\
         /// URL normalization would change which endpoint receives the request.\n\
         \x20   pub(crate) fn path(self) -> Result<String, &'static str> {\n        match self {\n",
    );
    for op in operations {
        if op.params.is_empty() {
            out.push_str(&format!(
                "            Op::{} => Ok(String::from(\"{}\")),\n",
                op.variant, op.path
            ));
            continue;
        }
        let mut template = op.path.clone();
        let mut args = Vec::new();
        for (name, field) in &op.params {
            template = template.replace(&format!("{{{name}}}"), "{}");
            args.push(format!("segment({field}, \"{name}\")?"));
        }
        out.push_str(&format!(
            "            Op::{}{} => Ok(format!(\"{}\", {})),\n",
            op.variant,
            pattern(op),
            template,
            args.join(", ")
        ));
    }
    out.push_str("        }\n    }\n}\n");
    out
}

fn wildcard(op: &Operation) -> &'static str {
    if op.params.is_empty() { "" } else { " { .. }" }
}

fn pattern(op: &Operation) -> String {
    if op.params.is_empty() {
        String::new()
    } else {
        let fields: Vec<&str> = op.params.iter().map(|(_, field)| field.as_str()).collect();
        format!(" {{ {} }}", fields.join(", "))
    }
}

fn render_error_codes(spec: &Value) -> Result<String, String> {
    let codes = spec["components"]["schemas"]["ApiError"]["properties"]["error"]["properties"]
        ["code"]["enum"]
        .as_array()
        .ok_or("spec has no ApiError code enum")?;
    let mut out = String::from(HEADER);
    out.push_str(
        "crate::open_enum! {\n\
         \x20   /// The `error.code` of an API error response. The server adds codes over\n\
         \x20   /// time; a code this version does not know decodes as `Unrecognized`.\n\
         \x20   pub enum ErrorCode {\n",
    );
    for code in codes {
        let code = code.as_str().ok_or("error code is not a string")?;
        out.push_str(&format!(
            "        /// `{code}`\n        {} = \"{code}\",\n",
            code.to_upper_camel_case()
        ));
    }
    out.push_str("    }\n}\n");
    Ok(out)
}

fn rustfmt(source: &str) -> Result<String, String> {
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--emit", "stdout"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .map_err(|error| format!("cannot run rustfmt: {error}"))?;
    child
        .stdin
        .take()
        .expect("stdin is piped")
        .write_all(source.as_bytes())
        .map_err(|error| format!("cannot write to rustfmt: {error}"))?;
    let output = child
        .wait_with_output()
        .map_err(|error| format!("rustfmt failed: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "rustfmt rejected generated code: {}",
            output.status
        ));
    }
    String::from_utf8(output.stdout)
        .map_err(|error| format!("rustfmt output is not UTF-8: {error}"))
}
